INSERT INTO transfer_targets VALUES(10,'2026-summer','Modou Kéba Cissé','시세',1944705,'LASK → Aston Villa','CB','RCB','CONFIRMED','00200001420237413X9814X84',60.89999999999999858,31.19999999999999929,6,6.769999999999999574,'cb_defender','Balanced','cb_bpd','Aggressive',0.8900000000000000133,'CONFIRMED incoming: pre-contract signed summer 2025, joins for 2026/27 after a season at LASK. Measured: right-of-centre CB (60.9,31.2), Ball-Playing Defender/Aggressive fit 0.89 — same fit family as Konsa (0.88). Natural RCB cover/heir; Austrian Bundesliga level caveat. [2026-07-15 재확인] RotoWire: 공식 합류 확인(사전계약, LASK에서 2026년 여름 발효). [2026-07-15 3축+스탯 — 유지] 6경기: kp 0·xA .01·듀얼 3.8·태클 1.5·패스 84% — 진전 산출 없는 수비형, cb_defender/Balanced 처방 유지(움직임은 bpd/Aggressive .89로 콘사형 스텝아웃 — 기능축 우선). LASK 리그 수준 캐비앗. [2026-07-28 FC26 통합 확인] 숙련 cb_defender+·cb_stopper+ — bpd 마커 없음, 기능축 처방(cb_defender/Balanced)을 FC26이 지지 — 확정.','https://readastonvilla.com/2026/05/14/modou-keba-cisse-the-future-aston-villa-player-who-is-shining-in-austria/ ; SofaScore API player 1944705 (2026-07-02)','CONFIRMED signing; measured from LASK (league-strength caveat). / 2026-07-15: 공식 완료 확인 — CONFIRMED 유지.','시세');
INSERT INTO transfer_targets VALUES(13,'2026-summer','Alysson','알리송',1631879,'Aston Villa (2026-01, Grêmio €10M)','RW','RM','OWNED','001640014X000380003600011',83.20000000000000284,59.70000000000000284,6,6.75,'wm_winger','Attack','wm_insidefwd','Balanced',0.8469999999999999752,'ALREADY OWNED: joined from Grêmio for €10M in January 2026; young (2006) right winger not yet in the analysis roster. Measured: genuine wide-right (83.2,59.7) — the squad''s only natural touchline RW; fit Inside Forward/Balanced 0.85. Prescription Winger/Attack to use his width+pace profile distinct from McGinn/Bowen half-space types. [2026-07-15 3축+스탯 — 유지] 6경기: xG .10·xA .03·kp .3·듀얼 3.7·드리블 1.0 — 창조 산출 미성숙 직선 윙어, winger/Attack 처방 유지(움직임 최근접은 insidefwd/Balanced .847). [2026-07-29 우측 브리프 정합 검증] 디아비 템플릿 코사인 .839, 침투 서명 전방 0.54·자기진영 0.23(하지무사·음바예보다 낮음 = 침투 빈도 열위), 터치라인 열 0.60 = 스쿼드 유일 천연 터치라인 RW. 함의: 브리프를 부분 충족하는 보유 자원이라 "우측이 절대 공백은 아니다"는 협상 레버리지. 19세로 주전 고정은 리스크.','https://www.fotmob.com/teams/10252/transfers/aston-villa ; SofaScore API player 1631879 (2026-07-02)','OWNED; measured mixes Grêmio+Villa minutes (sample caveat).',NULL);
INSERT INTO transfer_targets VALUES(18,'2026-summer','Anis Hadj Moussa','하지 무사',1218066,'Feyenoord','RW','RM','MEDIUM-HIGH','312691114X000140002400001',76.90000000000000569,69.29999999999999716,6,7.549999999999999823,'wm_insidefwd','Attack','wm_insidefwd','Attack',0.923000000000000042,'ADVANCE TALKS (Villa vs Newcastle); player prioritising a PL move for 26/27, Feyenoord ask ~€35m. Measured: high-and-wide right winger (76.9,69.3), Inside Forward/Attack fit 0.92 — the HIGHEST RM-slot fit sampled (Bowen 0.88) AND the highest avg rating of all targets (7.55). Eredivisie level caveat. [2026-07-03 watch: talks well underway with both Villa & Newcastle, expected to accelerate; Newcastle edge — Villa CL squad-registration restriction (UEFA fine) may hamper. Feyenoord ~€35m. Grade unchanged.] [2026-07-09 watch: TransferFeed/Yahoo — 빌라·뉴캐슬이 "most advanced in discussions" 공식 표현으로 보도, 선수 본인도 PL 선호 재확인. MEDIUM-HIGH에서 HIGH 상향.] [2026-07-15 재확인] Sacha Tavolieri(2티어급): "advanced talks" 보도 재확인, 대리인이 빌라·뉴캐슬 지목. 페예노르트 €35m 고수. [2026-07-15 3축+스탯 — 교정 winger/Attack→insidefwd/Attack] 6경기 스탯: xG .42·xA .46·kp 3.2·드리블 2.0·3골(평점 7.50 후보군 1위). 기능=득점+창조 양방 엘리트 = 컷인형 인사이드 포워드. 현커널 움직임도 insidefwd/Attack .923 최상 — 2축 일치로 교정. [2026-07-19 재검증] advanced talks 근거였던 Sky Sport Switzerland(Tavolieri)는 영국 Sky Sports 공식(tier-1)과 별개 매체로 재분류 — HIGH 유지 근거 약화. 선덜랜드 신규 문의·첼시 모니터링으로 경쟁 확대. [2026-07-27 21시 최신화] Sacha Tavolieri(Sky Sport Switzerland, 신뢰도 높은 이적 전문기자) — 빌라·뉴캐슬 "advanced talks". 페예노르트 €35m 요구, 선수 측(에이전트 Dahmane)은 PL행 확정적 의사 표명, 사우디 오퍼 거절. 뉴캐슬과 양자 경쟁 구도 유지. [2026-07-28 FC26 통합 확인] 실측 0.923 + 숙련 w_insidefwd+(동계열 W그룹) + #드리블러/#곡예사 — 처방 확정. [2026-07-29 14시 재확인 — 유지] 빌라·뉴캐슬이 최선두 협상(TransferFeed), Feyenoord €35m 최소가·2030 계약. Sky: 선수 잉글랜드행 희망(사우디 관심 불구). 대리인 "이번 여름 이탈 예상". [2026-07-29 우측 브리프 정합 검증] 디아비 23/24 실측 템플릿 대비 코사인 .835, RM 커널 insidefwd/Attack .923, 침투 서명 = 전방 2행 0.76(전 후보 최고)·자기진영 2행 0.14 → Tanswell 브리프("뒷공간 반복 침투 빠른 우측 윙어") 정합 1순위. 평점 7.55도 전 타깃 최고. 캐비앗: 에레디비시 레벨. 배치 제약 — B1(해방 우측)에서 Attack 가용, A(가르나초 해방)에서는 좌우 동시 해방 금지(obs#27)로 Support 강제.','https://thehardtackle.com/transfer-news/2026/06/30/aston-villa-newcastle-united-advance-talks-to-sign-anis-hadj-moussa/ ; SofaScore API player 1218066 (2026-07-02); Sacha Tavolieri(Sky Sport Switzerland); TeamTalk; TheHardTackle; Football Insider','MEDIUM-HIGH 유지 — 신뢰도 높은 기자의 협상 진전 보도, 단 빌라 단독이 아닌 뉴캐슬과 경쟁 중이라 HIGH 미달.','하지무사');
INSERT INTO transfer_targets VALUES(30,'2026-summer','Tammy Abraham','타미 아브라함',610766,'Aston Villa','ST','ST','OWNED','01855255648X8415422010200',47.39999999999999858,59.0,4,6.849999999999999645,'st_target','Attack','st_false9','Attack',0.5210000000000000186,'ALREADY OWNED: 2026-01-27 베식타슈에서 ~£18m로 빌라 복귀(1일 만에 재이적), 그 시즌 유로파리그 우승. 여름 루머 대상이 아니라 보유 선수(알리송과 동일 케이스) — 사용자 요청으로 OWNED ST 옵션으로 편입. 실측(반시즌 통틀어 45분+ 4경기 전부 ST): 중앙-약간좌측·깊은 풋프린트 (47.4,59.0), 평균 6.85. 최근접 st_false9/Attack 0.52 — 왓킨스(st_advanced 자기커널)·기라시 0.80·브로베이 0.75·파르도 0.87보다 명확히 낮음. 처방은 타깃/홀드업 아키타입 반영 st_target/Attack. 표본 캐비앳: 왓킨스의 로테이션 백업이라 45분+ 경기가 반시즌 4경기뿐이고 전부 교체 출전(추격 상황 드롭) → 깊은 편향된 풋프린트, 선발 표본 아님. [2026-07-15 3축+스탯 — 유지] 6경기: xG .25·3골·kp 1.0·드리블 0 — 타깃형 피니셔, st_target/Attack(공중 플랜B, obs#19) 유지.','https://www.avfc.co.uk/news/2026/january/27/signing-aston-villa-confirm-tammy-abraham-signing/ ; SofaScore API player 610766 (2026-07-03)','OWNED — 이적 루머 아님(2026-01 합류확정 보유선수). 측정 신뢰 MEDIUM(표본 4경기·전부 교체출전·맥락 편향, 45분+ 6경기 미달).',NULL);
INSERT INTO transfer_targets VALUES(75,'2026-summer','Pervis Estupiñán','에스투피냔',805465,'AC Milan','LB','LB','MEDIUM-HIGH','21000X3100610007200032100',16.10000000000000143,49.10000000000000142,6,6.870000000000000106,'fb_att_wb','Support','fb_att_wb','Support',0.945999999999999953,'좌측면 전 깊이 커버 공격형 레프트백. 실측 6경기(세리에A, 322pt) 중심 tool(16,49). 커널 fit fb_att_wb/Support 0.946 (2위 fb_inverted/Build-Up 0.89). 밀란 아모림 구상 외, 호가 ~€14m. [2026-07-14 야간 재확인] Romano: "AVFC 좌측백 3인 숏리스트 중 상위, 딜 진행중, 협상 계속"(YouTube) — 단 조건 미확정, 데포르티보 라코루냐 경쟁 참전. 디뉴 대체가 아니라 마첸 백업/뎁스 역할로 영입(주전 보장 아님). [2026-07-15 재확인] Matteo Moretto(로마노 채널, 준1티어급): "협상 공식 개시" 확인 — 밀란-빌라 간 클럽 대 클럽 협상 단계 진입. 이적료 격차(€18-20m vs €10-12m)만 남음. 협상 단계 확인으로 HIGH 상향. [2026-07-15 3축+스탯 — 유지] 6경기: 패스 89%·태클 1.3·kp .8 — 견실 전진 LB. att_wb/Support 유지(마첸 07-15 교정 처방과 동일 — 경쟁 구도 명확). [2026-07-17 재확인] Romano(1티어): 개인조건 합의 완료. 클럽간 협상 advanced("non-stop contacts" — Longo), 이적료 격차 €12m vs €18-20m에서 Gazzetta €15m 절충설. 완료 임박 국면. [2026-07-18 재확인] 클럽간 최종 협상 단계 — 밀란 €18-20m vs 빌라 €10-12m에서 €15m 절충 근접(Gazzetta), "다음 주 초 이전 타결" 양측 낙관. 결정적 미팅 수일 내. [2026-07-19 재검증 강화] Romano(1티어, 7/16-17): 빌라가 에스투피냔과 개인조건 합의, 선수도 이적 희망, AC밀란과 이적료 협상 계속. 텔레그래프(2티어)도 advanced 확인. 이적료 격차만 남음(18-20m 밀란 요구 vs 10-13m대 빌라). [2026-07-27 상태변화] 정체 심화 → MEDIUM-HIGH 하향. Amorim이 밀란 프리시즌 호주 투어까지 에스투피냔을 직접 평가하겠다며 매각 승인 보류(Tuttosport/Football Italia), 일부 보도는 완전 차단 가능성 시사. 선수는 개인조건 합의·PL 복귀 희망 유지, 이적료 격차 €15-16m 절충설(Gazzetta). 반론: Pellegatti — "감속설은 카르디날레의 몸값 인상용 전술, 협상 계속·타결 임박". 개인합의는 유지되나 클럽 승인 리스크로 HIGH 요건(완료 임박) 미충족. [2026-07-27 21시 최신화] 상충 지속: TheHardTackle(Calciomercato 경유)는 "아모림이 매각 차단" 재확인 보도, 반면 밀란 기자 Antonio Vitello는 "글래스고 이동 명단에 없음"을 근거로 이적 임박 가능성 시사. 로마노·벤 제이콥스(1티어)의 기존 "개인조건 합의·advanced talks" 보도는 유효. [2026-07-28 FC26 통합 확인] 실측 0.946 압도 — 유지. 캐비앗: FC26 숙련은 fb_wingback+(윙백)·wm_winger+, att_wb 숙련 마커는 없음. [2026-07-29 14시 재확인 — 유지] 아모림(밀란 신임감독)이 이적 일시 블록(7/25, Accomando) — 개인합의(2030년까지) 완료·클럽간 ~£13m 근접 상태에서 보류. 셀틱전 스쿼드 제외는 이적 상황 연관 보도. 밀란 최종 판단 대기.','Moretto via SempreMilan https://sempremilan.com/moretto-aston-villa-enquire-milan-estupinan ; SofaScore player/805465 (6 Serie A ~2026-05-10) ; milanreports 7/21·7/23 (Athletic·Tuttosport 경유, 재검증 07-26) ; [07-27] Yahoo/Football Italia "Amorim asks Milan to hold off on Estupinan deal", milanreports 7/21·7/23; TheHardTackle(Calciomercato); Antonio Vitello(밀란 전담); Fabrizio Romano; Ben Jacobs; Sports Mole','MEDIUM-HIGH 유지 — 클럽 차단설과 이적 임박 신호가 병존, 07-27 09시 하향 판정 그대로 유지.','에스투피냔');
INSERT INTO transfer_targets VALUES(77,'2026-summer','Johan Manzambi','만잠비',1518931,'SC Freiburg','CM','LDM','CONFIRMED','33414775548X6447877220320',43.60000000000000142,51.79999999999999716,6,7.620000000000000106,'dm_dlp','Roaming','dm_dlp','Roaming',0.8120000000000000551,'완전 box-to-box, 중앙 전역 커버(온아나 대체). 실측 6경기(분데스리가, 363pt) 중심 tool(44,52). 커널 fit LDM dm_dlp/Roaming 0.812 (RDM는 0.544로 약함 → 좌중앙 성향, LDM 전용). 평균 7.62 최상. [2026-07-14 확정] 빌라 합류 확정(사용자 확인). [2026-07-15 재확인] Romano "here we go": €60m+ 구두합의, 개인조건 완료. 뉴캐슬 £49m 구두합의를 히잭. 아직 공식 발표(메디컬) 전 단계. [2026-07-15 3축+스탯 — 유지] 6경기: 듀얼 7.5(후보군 1위)·xG .18·xA .16·태클 1.8·평점 7.40 — 박투박+창조 겸비(오나나 공백 임무에도 부합), dlp/Roaming 유지. [2026-07-17 재확인] 메디컬 완료(7/16), Romano "몇 시간 내 발표". Visit Rwanda 스폰서 관련 잡음(DRC 가족사) 해소, 5년 계약 — 클럽 레코드 £50m+. [2026-07-18 재확인] 공식 발표 완료(7/17 저녁) — £59.5m(€70m) 클럽 레코드, 장기계약. 뉴캐슬 하이잭 최종 성사. [2026-07-21 멀티포지션] CAM(대표팀 전진 실측 0.817)·LM(재배치 0.700) 행 추가 — 슬롯별 별도 그리드 참조. [2026-07-28 FC26 통합 확인] LDM: 숙련 dm_dlp+·cm_dlp+가 처방과 일치 — 확정. 테크니컬 PS·드리블85.','Romano/Ornstein/Sky Germany 하이잭 보도(€70m 합의 임박); SofaScore player/1518931 (6 Bundesliga ~2026-05-16)','CONFIRMED — 합류 확정. 실측 신뢰 HIGH(6경기 전부 45분+, 363pt, fit 0.812). / 2026-07-15: 구단간·개인 합의 완료, 공식 발표만 대기 — CONFIRMED 유지. / 2026-07-18: 구단 공식 발표 — 완료.','만잠비');
INSERT INTO transfer_targets VALUES(91,'2026-summer','João Palhinha',NULL,364612,'Bayern Munich','DM','LDM','HIGH','002112323345365465X611221',53.70000000000000284,44.0,6,6.919999999999999929,'dm_holding','Ball-Winning','dm_widehalf','Build-Up',0.6800000000000000488,'바이에른과 시즌 로그론 + €25m 의무구매옵션 가능성 합의, 잉글랜드 이동 중(오나나 부상 공백 메우기). 온나나 십자인대 부상, 틸레만스 맨유行으로 보강 필요. [2026-07-27 21시 최신화] 로마노/애슬레틱(Tanswell) 경유: 팔리냐가 잉글랜드로 이동해 임대(+콜옵션 €25m) 마무리 단계 — 벤피카를 제치고 빌라가 사실상 확보. 다만 Tanswell은 "완전히 무산된 건 아니지만 빌라가 다른 일들로 바빠 잠시 정체"라고 톤 조절. 바이에른은 매각 강력 희망(€100m 펀드 확보 목적). [2026-07-28 FC26 통합 확인] 숙련 dm_holding+(수비/볼위닝/로밍)가 기능축 처방과 정확 일치 — 확정. DEF83/PHY84/공격성91/태클85·슬라이딩태클/브루저 PS. 캐비앗: 네거티브 PS "부상에 취약함". [2026-07-29 14시 재확인 — HIGH 유지] Plettenberg(Sky DE): 7/19 "영국행·합의" 보도 반박 — 합의 없음, 프리시즌 바이에른 합류. 현 상태: 빌라=대여+옵션 고수 vs 바이에른=€25m 완전이적 요구 교착. BILD "빌라가 바이에른의 최유력 매각처". 사우디·터키 관심 있으나 선수는 유럽 잔류 희망(가족).','https://www.transferfeed.com/clubs/aston-villa/15; Record(PT); GiveMeSport; SportsMole ; Plettenberg/Sky DE via onefootball·readastonvilla (2026-07-24, 재검증 07-26); Sports Mole; Yahoo Sports/Bavarian Football Works("on verge"); Jacob Tanswell(Athletic, 팟캐스트); CaughtOffside','HIGH 유지 — 임대+콜옵션 구조로 사실상 합의 임박, 톤다운 코멘트 있으나 실행 단계 진입.','팔리냐');
