INSERT INTO transfer_targets VALUES(95,'2026-summer','João Gomes','주앙 고메스',1015267,'Wolverhampton','DM/CM','LDM','CONFIRMED','11111551335X5443756411211',47.0,47.10000000000000142,6,6.650000000000000355,'dm_holding','Ball-Winning','dm_dlp','Roaming',0.7970000000000000417,'틸레만스 대체 영입 — 클럽간 합의(초기 £34.6m+애드온 £4.3m, 총 ~£38m), 금주 메디컬 예정. 아틀레티코행이 멘데스-구단 갈등으로 결렬된 것을 빌라가 인터셉트. [2026-07-17 실측+3축] 최근 6경기(45분+): 태클 3.7·듀얼 7.0·kp .3·xA .04 — 기능=순수 볼위너+박투박 엔진(카마라형). 움직임 최근접 dlp/Roaming .797(LDM — 우측 배치 .638로 좌측 우세). 기능축 우선(obs#31)으로 처방 dm_holding/Ball-Winning. [2026-07-18 재확인] 메디컬 금요일(7/17) 진행 — 포르투갈 캠프 이탈·귀국 확인, 개인조건 2031년 계약 합의(Schira). 공식 발표 임박. [2026-07-28 FC26 통합 확인] 기능축 우선 처방(dm_holding/Ball-Winning) 유지. 캐비앗: FC26 숙련은 boxcrasher/widehalf/dlp/cm_dlp — holding 마커 없음. 압박검증·슬라이딩태클 PS는 볼위닝 기능 지지. [2026-07-29 홀딩 처방 재검증 — 유지 확정] 현행 커널 재검산: dlp/Roaming .797 정확 재현(stale 아님), holding/Ball-Winning은 .45로 움직임 불일치. 그러나 ①실측 홀딩 동료와 직접 유사 — 온아나 그리드 .835/카마라 .805 (둘 다 움직임 코사인은 dlp .87이었으나 기능축으로 holding 처방된 동일 패턴, obs#32) ②기능=창조 전무(kp .3·xA .04) — dlp 지시는 전개 산출 없는 선수에게 공급 책임 부여하는 모순 ③요구역할=카마라 장기부상 중 앵커 대체+obs#27 블록 전제. 3축 모두 holding 지지 → dm_holding/Ball-Winning 유지. 숙련 캐비앗 대응: holding 미숙련 페널티 확인 시 차선은 dm_boxcrasher/Balanced(.701, 숙련 보유+박투박 기능 부합)이며 dlp가 아님. left-release-A 프리셋의 LDM dlp 공급 요건은 고메스 기능으로 충족 불가 — 진성 DLP형(사라·베르그발) 영입 또는 boxcrasher 절충 필요.','ESPN(1티어, sources) fee agreed ~€40m ; Fabrizio Romano(1티어) "here we go" £34.6m+£4.3m (2026-07-16~17) ; SofaScore API player 1015267 (2026-07-17, 최근 6경기 45분+)','CONFIRMED — 1티어 이중 확인(ESPN+Romano here we go), 메디컬만 남음(만잠비·틸레만스 선례와 동일 단계). 실측 HIGH(6경기 전부 45분+). / 2026-07-18: 메디컬 진행 — 발표만 대기.','고메스');
INSERT INTO transfer_targets VALUES(97,'2026-summer','Julián Quiñones','훌리안 퀴뇨네스',843114,'Al-Qadsiah','ST','ST','MEDIUM-HIGH','10X5114763023410113100100',57.0,67.0,6,7.679999999999999716,'st_false9','Attack','st_false9','Attack',0.8319999999999999619,'왓킨스 대체 후보 — 멕시코 월드컵 4골 1도움(잉글랜드전 득점 포함)으로 빌라 스카우트 반함, 대리인 접촉 "최근 강화"(Tavolieri). 사우디 알카디시아 2029 계약·릴리스 $200m이 장벽, 첼시·헤노아·아틀레티코 경쟁. [2026-07-17 실측+3축] 최근 6경기(45분+, 사우디리그): xG 1.10·7골·xA .31·평점 7.68 — 산출 폭발적이나 리그 수준 캐비앗 필수. 움직임 st_false9/Attack .832 최상(드롭·링크형 피니셔), 기능은 순수 피니셔. [2026-07-18 전술핏 분석] ①아키타입: 기라시와 그리드 .914(사실상 동일 유형 — false9 드롭형 피니셔 2명이 후보군), 듀란 실측과 .876. obs#18 "듀란형 ST(스피드+파워)" 니즈 대조 — FC26 PAC 88(왓킨스 77·기라시 72 압도)+PHY 83으로 후보군 중 듀란형 정의 최근접. ②10번 공존성: 로저스 CAM 그리드와 겹침 .750 — 왓킨스(.891)보다 낮음. 실측 중심이 우채널(57.0) 드리프트라 중앙-좌 성향 10번과 상보적 — 로저스 잔류 시나리오에서도 공간 충돌 개선. ③왓킨스 3역 임무 대조: 박스 점유(xG 1.10)·드롭/링크(false9 .832)·채널런(우측 드리프트) 전부 충족 — 단 좌우 방향이 왓킨스와 반대(왓킨스 좌, 퀴뇨네스 우). ④수비: 자기진영 .127 — ST 슬롯은 프레스 첫줄이라 미드블록 이슈 아님(프레스 강도 실측은 미확보 캐비앗). 커널 확정 false9/Attack .832, 공중 플랜B 대안 target/Balanced .726(아브라함 역할 겸임 가능). 최대 리스크는 사우디 리그 수준 보정과 29세(리세일 없음). [2026-07-19 재검증] Sky Sport(Tavolieri, tier 애매) 접촉 강화 확인, 정식 오퍼는 아직 없음. Romano(1티어)는 첼시 관련설만 부인 확인 — 빌라 진전과 무관. 등급 유지. [2026-07-20 21시(4차) 재검증] Sky Sports 인용 주장(GiveMeSport 재인용, 원문 미확인)으로 빌라 문의설 — 원문 크로스체크 실패, 등급 유지. [2026-07-27 21시 최신화] Sacha Tavolieri(Sky Sport) 경유: 월드컵 활약 이후 빌라 스카우트가 확신, 대리인 접촉 "최근 강화" — 단 공식 오퍼는 아직. 첼시·제노아·아틀레티코와 경쟁, $200m 바이아웃은 협상용 명목가로 판단. [2026-07-28 FC26 통합 확인] 실측 0.832 + 숙련 st_false9+ 일치 + 칩슛/래피드/PAC88·점프95 — 처방 확정. [2026-07-29 14시 재확인 — 유지] 공식 bid 없음, 대리인 접촉 강화(WC 후). 장애물: 사우디 고임금(감봉 필요)+명목 $200m 릴리즈 클로즈(협상용). SCR 벌금 맥락상 유출 선행 필요.','Sacha Tavolieri(Sky Sports 계열, 2티어) 컨택 강화 보도 ; TeamTalk "intensify contact" ; Football Insider ; SofaScore API player 843114 (2026-07-17, 사우디리그 최근 6경기 45분+); Sacha Tavolieri; Sky Sports(Yahoo 경유); FootballPlace; Tribuna; InsideFutbol','MEDIUM-HIGH 유지 — 접촉 강화 확인되나 공식 오퍼 부재, 경쟁 클럽 다수로 HIGH 미달.','퀴뇨네스');
