INSERT INTO transfer_targets VALUES(123,'2026-summer','Nicolas Jackson',NULL,NULL,'Chelsea','ST','ST','HIGH','457725X496434211211100000',48.0,68.79999999999999716,6,7.450000000000000177,'st_advanced','Support','st_advanced','Support',0.7520000000000000017,'로저스 매각(첼시 £117m)으로 확보한 자금 재투자 대상, 에메리-비야레알 인연. [2026-07-24 갱신] 가르나초 CONFIRMED로 정리된 후에도 별개 딜로 논의 지속 확인 — 첼시가 £65m 요구가 명확히 설정(협상 기준가), 잭슨 본인도 정규 출전시간을 위해 빌라 이적에 열려있음("open to a move"). 로마노(1티어) "에메리 여전히 팬" + 양 구단 논의 지속 확인. 빌라 재정 제약으로 £60m 이하 필요 시사(협상 지속 근거) — 협상 단계 진입으로 등급 상향. [2026-07-27 21시 최신화] Sky Sports(1티어) 공식: 빌라가 조건 타진 중이며 "positive discussions" 진행. 첼시 호가 £60m+, 빌라는 클럽 레코드 경신 예상. 로저스·가르나초에 이은 첼시-빌라 세 번째 딜로 그림 완성. [2026-07-28 FC26 통합 확인] 실측 0.752 + 숙련 st_advanced+ 일치 — 확정. Support 포커스는 하강 링크 성향(실측)과 게임체인저/테크니컬 PS 부합. [2026-07-29 14시 재확인 — HIGH 유지] Plettenberg(7/28): 첼시·선수 측과 직접 협상 진행 중(영구 or 대여), 합의 아직 없음. 첼시 호가 £65m(영구 선호), 빌라 클럽레코드 경신 준비 보도(GMS). 호재: 첼시가 웰벡(브라이튼) 영입 검토 — 잭슨 방출 여지 확대.','Fabrizio Romano(1티어) 관심·에메리 각별 신뢰 확인 ; Football Insider(2티어) £60-65m 요구 ; Yahoo Sports "step up talks" ; SofaScore API player 1085381 (2026-07-21) ; thehardtackle(2026-07-19,21) 논의/가격 설정 ; Yahoo Sports(잭슨 open to move) ; teamtalk(2클럽 논의 중) ; Romano X 2079473534951211218 ; teamtalk nicolas-jackson-villa-break-transfer-record (재검증 07-26); Sky Sports; BBC(gossip); TeamTalk; Africasoccer','HIGH 유지 — 1티어(Sky) 협상 진행 확인, 기록적 이적료 임박 분위기.','잭슨');
INSERT INTO transfer_targets VALUES(125,'2026-summer','Iliman Ndiaye',NULL,NULL,'Everton','RW','RM','MEDIUM-HIGH','112273215X101370002410001',71.20000000000000284,63.39999999999999858,6,6.870000000000000106,'wm_insidefwd','Balanced','wm_insidefwd','Balanced',0.8830000000000000071,'로저스 대체 우측 자원 후보, 맨유와 경쟁. [2026-07-27 21시 최신화] Fabrizio Romano(1티어): "몇 주 전 빌라와 약간의 대화가 있었다" — 초기 단계 확인, 맨유도 경쟁(라쉬포드 이적 우선 필요로 진전 더딤). 에버턴 £70m 밸류에이션이 핵심 걸림돌. [2026-07-28 FC26 통합 확인] 실측 0.883 명확(2위 winger 0.825) — 숙련은 wm_winger+뿐이나 데이터 우선(맥긴 선례, 숙련은 스탯 너프 아님). DRI86/테크니컬/#드리블러가 인사이드 포워드 기능 지지. [2026-07-29 14시 재확인 — 유지] Romano 확인: "빌라가 몇 주 전 대화했다" — 맨유·해외 클럽과 경쟁. 에버튼 ~£70m 요구(계약 연장 협상 정체). 탐색 단계, 서머빌 대안 병행 검토. [2026-07-29 우측 브리프 정합 검증] 디아비 템플릿 코사인 .864(전 후보 최고 = 형태 최근접), 침투 서명 전방 0.63·자기진영 0.15. 프로필은 브리프 정합이나 £70m 밸류에이션이 실행 장벽 — 형태 순위 1위/실행 가능성 하위.','Fabrizio Romano(1티어) 컨택 확인 ; astonvillanews.co.uk £60m 딜 ; Arsenal Pulse/Lorenzo Jabota(3티어, 보조 근거) ; SofaScore API player 914309 (2026-07-21); Fabrizio Romano; ESPN; Yahoo Sports; AstonVillaNews; bet365 News','MEDIUM-HIGH 유지 — 1티어가 초기 대화 확인, 공식 오퍼는 아직 없음.','은디아예');
INSERT INTO transfer_targets VALUES(126,'2026-summer','Gabriel Sara',NULL,NULL,'Galatasaray','CM','RDM','MEDIUM-HIGH','72226XX899678845644522222',48.20000000000000284,56.20000000000000284,6,7.349999999999999645,'dm_dlp','Roaming','dm_dlp','Roaming',0.6069999999999999841,'티엘레만스 이적·카마라 부상 공백 메우는 중앙 자원 후보. 팔리냐와 함께 검토 중. [2026-07-27 21시 최신화] TeamTalk(2티어): 빌라·뉴캐슬이 대리인과 접촉(£25m). 단, 빌라가 동일 에이전트 라인(주앙 고메스)으로 이미 미드필더를 영입해 긴급성 낮아짐 — 나폴리·뉴캐슬도 경쟁. 갈라타사라이는 매각 의향 있으나 공식 오퍼는 아직. [2026-07-28 FC26 통합 재판정] 기존 처방 dm_holding/Ball-Winning은 FC26 프로필과 불일치(차단력65·태클66/59 — 볼위닝 기능 없음). 실측 argmax dm_dlp/Roaming 0.607 + 긴패스85·커브84·데드볼/예리한패스/인벤티브 PS = 배급형 → dm_dlp/Roaming으로 교정. 캐비앗: FC26 숙련은 CM/CAM 계열(cm_b2b+·cam_playmaker+)뿐이라 RDM 기용 시 역할 숙련 마커 없음, 적합 절대값도 0.607로 낮음. [2026-07-29 14시 재확인 — 유지] 빌라·뉴캐슬이 측근 접촉(공식 오퍼 없음), Football Insider "빌라 선두". 갈라타사라이 최소가 €35m(Fanatik) — 투람 영입 재원으로 매각 계획. 선수 PL 이적 긍정적.','Football Insider(2티어) "hopeful of winning race" ; TeamTalk(2티어) £25.5m 오퍼 보도 ; CaughtOffside(2티어) ; SofaScore API player 913593 (2026-07-21); TeamTalk; GiveMeSport; TheHardTackle; Yahoo Sports','MEDIUM-HIGH 유지 — 접촉 단계 확인되나 빌라의 우선순위가 낮아져 진전 속도는 느림.','사라');
INSERT INTO transfer_targets VALUES(127,'2026-summer','Rafael Leão',NULL,NULL,'AC Milan','LW','LM','MEDIUM-HIGH','245108X610434302101000100',34.10000000000000142,65.70000000000000284,6,7.030000000000000248,'wm_wideplm','Attack','wm_wideplm','Attack',0.7800000000000000266,'로저스 대체 좌측 윙 후보, 이적 요청서 제출한 상태. [2026-07-27 21시 최신화] La Gazzetta dello Sport: 레앙이 밀란에 공식 이적 요청서 제출, 빌라를 PL 측 최우선 구단으로 지목. 호가는 초기 £50m/€60m에서 €50m 선으로 하락 조짐. 단 Tuttosport는 "에스투피냔 협상 중 나온 탐색성 문의" 수준이라 명시 — 클럽 간 공식 협상 개시는 아직. [2026-07-28 FC26 통합 확인] 실측 wideplm/Attack 0.780 vs insidefwd 0.719 — Δ0.061 유의미, 데이터 우선 유지. 캐비앗: FC26 숙련은 w_insidefwd++(레벨2)·wm_insidefwd+ — 게임 내 숙련 마커는 insidefwd에만 있음. PAC93/#속도광/#드리블러는 양쪽 다 지지. [2026-07-29 14시 재확인 — 유지] 이적요청서 효과로 호가 연화(€60m→€50m, £38m선 가능 보도). 빌라=주요 PL 수터(Gazzetta)이나 공식 오퍼 미제출. 상충 신호: football-italia "선수 마음은 아스날". 멘데스가 행선지 키 보유.','La Gazzetta dello Sport(2티어급 이탈리아 매체) ; Sports Mole(2티어) "surprise move" ; Get Italian Football News ; SofaScore API player 851284 (2026-07-21) ; Gazzetta via yahoo fenerbahce-submit-bid ; sempremilan aston-villa-leao-approach (재검증 07-26); La Gazzetta dello Sport; Tuttosport(경유); Sports Mole; TheHardTackle; SportMediaset(경유)','MEDIUM-HIGH 유지 — 선수의 공식 이적 요청과 빌라 우선순위 지목은 확인되나, 구단 간 공식 협상은 탐색 단계.','레앙');
