INSERT INTO transfer_targets VALUES(130,'2026-summer','Martin Baturina','마르틴 바투리나',1090019,'Como','AM','CAM','MEDIUM-HIGH','532128X651552113421101000',37.20000000000000285,61.5,6,7.120000000000000106,'cam_halfwinger','Balanced','cam_halfwinger','Balanced',0.7109999999999999654,'틸레만스(→Man Utd)·로저스(→Chelsea) 유출 공백을 메울 창조형 미드필더 후보. 월드컵 잉글랜드전 골로 주가 상승, Como는 "매각 불가" 방침이었으나 최근 태도 완화 보도. 25/26 34경기 8골 4도움. [2026-07-27 21시 최신화] 빌라의 공식 오퍼(€50-55m)가 코모에 거절됨 확인(Football365/Football365 경유 코모 회장 발언) — 코모는 €80m 고수, 바이에른도 새로 경쟁 합류. 오퍼 제출까지는 갔으나 거절되어 HIGH 승격 요건(합의 단계) 미충족. [2026-07-28 FC26 통합 확인] 실측 argmax 0.711(2위 classic10/Versatile 0.691) 유지 — 데이터 우선. 캐비앗: FC26 숙련 cam_playmaker+·예리한패스/인벤티브/퍼스트터치 PS는 플레이메이커 성향 — 게임 내 숙련 마커를 원하면 cam_playmaker/Roaming(0.676) 대안. [2026-07-29 14시 재확인 — 유지] 빌라 공식 제안 €50-55m(£43-48m) 제출 → Como 거절(Gazzetta via SW), €80m 요구·2030 계약이라 매각 불요 입장. 경쟁: 맨유·토트넘·바이에른. 로저스 매각 재원으로 증액 여지.','Sky Sports(Sky Italia 인용, 1티어): Villa 관심 확인, Como 요구 €80m; Athletic Jacob Tanswell(1티어): Villa 지출 상한 £40m 언급 — 재정 제약 캐비앗; Football365(코모 회장); Football Fancast; GiveMeSport; Yahoo Sports; CaughtOffside; SofaScore API /player/1090019 events+heatmap+statistics (2026-07-28 수집)','MEDIUM-HIGH 유지 — 공식 오퍼 제출·거절까지 진행되었으나 밸류에이션 격차가 커 HIGH 미달. / 2026-07-28 실측 완료: 클럽 6경기(세리에A 5·코파 1, 전부 45분+, 히트포인트 47~76) 포지션-순수 표본 — 월드컵·친선 6경기는 대표팀 맥락이라 제외. 코파(Inter전)는 라인업 표기 F이나 중심좌표가 세리에A CAM과 일치해 포함. 커널 적합 cam_halfwinger/Balanced 0.711(HIGH), 제노아 원정 1경기만 저지대 아웃라이어.','바투리나');
INSERT INTO transfer_targets VALUES(133,'2026-summer','Harvey Barnes','하비 반스',NULL,'Newcastle United','LW','LM','MEDIUM-HIGH','44221X4111521011100101100',29.89999999999999858,65.40000000000000569,235,6.599999999999999645,'wm_insidefwd','Balanced','wm_insidefwd','Balanced',0.929000000000000047,'빌라 좌측 와이드 보강 후보. 뉴캐슬과 2028년까지 계약 중이나 £38m 원 이적료 기준 협상 여지. 선수 본인이 미들랜즈 복귀(가족 근접) 희망한다는 전 CEO(Keith Wyness) 발언 다수, 25/26시즌 16골 활약 근거. [2026-07-27 21시 최신화] Keith Wyness(전 빌라 CEO, Football Insider 경유) — 선수 측 미들랜드 복귀 희망 확인. 뉴캐슬(하우 감독)은 잔류 희망하며 저항 중, £40m 밸류에이션. 램지-반스 스와프딜 가능성도 거론. [2026-07-28 FC26 통합 재판정] 현행 커널 재검산 argmax wm_insidefwd/Balanced 0.929(2위 동역할 Attack 0.843) — 기존 widemid/Build-Up 0.813은 구스캔 잔재로 교정. FC26 숙련 wm_insidefwd+·감아차기 PS·SHO81 3축 모두 일치. [2026-07-29 14시 재확인 — 유지] 뉴캐슬이 고든 바르사행(£70m 합의) 후 잔류 방침 경화 — 하우가 고든 대체 주전으로 검토, 블록 예정 보도(Football Insider). 선수 의사(미들랜즈 복귀)는 유효, ~£40m이면 매각 여지.','Football Insider247(2티어, 복수 기사: "closely watching"/"boost") ; TeamTalk(2티어) ; CaughtOffside(2티어) ; Keith Wyness(전 빌라 CEO) 발언(givemesport); Football Insider(Keith Wyness); TeamTalk; CaughtOffside; FootballTransferTavern','MEDIUM-HIGH 유지 — 선수 이적 희망 확인되나 뉴캐슬의 매각 저항으로 진전은 더딤.','반스');
INSERT INTO transfer_targets VALUES(134,'2026-summer','Lucas Bergvall','루카스 베리발',1391251,'Tottenham Hotspur','M','RDM','MEDIUM-HIGH','211230127X11273116X600100',67.29999999999999716,52.0,6,6.299999999999999823,'dm_dlp','Roaming','dm_dlp','Roaming',0.8060000000000000497,'[2026-07-27 신규] 틸레만스(맨유행 확정 유출) 대체 후보로 부상. Yahoo Sports "Sources: 빌라 재점화, 오픈 레이스"(Athletic 계열=1티어) + Football Insider·TeamTalk(2티어) 관심 보도, 이적료 ~£50m, 계약 2031. 경쟁 첼시·노팅엄 포레스트. ★댐퍼: Sky Michael Bridge — 스퍼스 "이번 여름 매각 불가" 입장 통보. 실측 THFC 최근 45+ 6경기(192pt, 시즌말 출전 급감=이적추진 정황): 중심 tool(67,52) 우중앙. RDM 커널 fit dm_dlp/Roaming 0.806(2위 boxcrasher/Balanced .77). LDM .43·CAM .50 부적합 → RDM 단일 등재(CM b2b .85지만 4-2-3-1에 CM 슬롯 없음). [2026-07-27 21시 최신화] Football Insider(2티어): 노팅엄 포레스트와 함께 선두 경쟁. 단 Sky Sports Michael Bridge(1티어)는 "이번 여름 이적 없다고 스퍼스가 선수에게 통보"라고 반박 보도 — 상충 유지. 선수 본인은 이적 희망 의사 재확인. [2026-07-28 FC26 통합 판정] opt 확정: 실측 argmax dm_dlp/Roaming 0.806(2위 boxcrasher/Balanced 0.772) + 압박검증 PS(전진 압박 아래 배급). 캐비앗: FC26 숙련 cm_b2b+·cam_playmaker+ — DM 계열 숙련 없음. [2026-07-29 14시 재확인 — 유지] 부정 신호: Sky Bridge — 스퍼스가 선수에게 잔류 통보, 클럽간 직접 접촉 없음(£57m 요구 가능). 선수는 이탈 희망 유지. 스퍼스 입장 연화 여부가 관건.','TransferFeed https://www.transferfeed.com/clubs/aston-villa/15 ; Yahoo Sports "Sources: Aston Villa to reignite Lucas Bergvall pursuit amid open race" ; footballinsider247.com ; SofaScore player/1391251 (6 THFC 45+ 2025-12~2026-04); Football Insider; TeamTalk; TheHardTackle; Sky Sports(Michael Bridge, 반박); DeadlineDayLive','MEDIUM-HIGH 유지 — 2티어 경쟁 보도 vs 1티어(Sky) 잔류 통보 반박이 상충, 등급 변동 없음.','베리발');
INSERT INTO transfer_targets VALUES(135,'2026-summer','Emerson Royal','에메르송 호이알',NULL,'Flamengo','RB','RB','MEDIUM-HIGH',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Matty Cash 백업 필요(안드레스 가르시아 게타페 임대行) — Villa가 Flamengo에 €9m 공식 제안 제출(6/23), Flamengo 거부 후에도 재제안 검토 중. Sky Sports Paper Talk(출처: The Athletic)가 협상 사실 보도, 선수 본인도 공개적으로 제안 수령 확인. 아직 합의 단계 아님(Flamengo 계약 2028까지, 판매 거부 기조) → MEDIUM-HIGH(1티어 협상 보도, 합의 전). [2026-07-29 14시 재확인 — 유지] 디테일 진전: 블록 주체=자르딤 감독(ESPN Brazil Andrade — "회장단은 승인 의향, 감독이 중단"). €9m→€10m 증액 제안도 보류됨. 선수는 공개적으로 긍정 반응, 협상 재개 여지 유효.','Sky Sports(via The Athletic) 2026-07; Yahoo Sports/Sports Mole 2026-07','PENDING MEASUREMENT — 헤드리스 실행, SofaScore 실측 미수행 (claude-in-chrome 연결 없음)','에메르송');
INSERT INTO transfer_targets VALUES(136,'2026-summer','Jonathan Rowe','조나단 로우',NULL,'Bologna','RW','RM','MEDIUM-HIGH',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'우측 윙어 브리프(obs 신규 — "뒷공간 침투 빠른 우측 윙어") 최전선 후보. Tanswell(1티어): 유력 타깃으로 부상, 이적 파라미터 공식 논의 진행. 세리에A에서 1대1 드리블·와이드 마무리로 성장한 잉글랜드 국적. 실측 그리드 없음 — 커널 적합·침투 서명(전방/자기진영 질량) 미산출로 프로필 정합 미검증. 협상 단계는 가장 앞서면서 우리 데이터는 공백이라 측정 최우선 대상.','Jacob Tanswell/The Athletic (via readastonvilla 2026-06-02)','PENDING MEASUREMENT — SofaScore 실측 미수행(2026-07-29 세션에서 API 레이트리밋으로 검색 엔드포인트 타임아웃). 다음 세션 최우선: 최근 6경기(45분+) 히트맵 → 디아비 템플릿 코사인·전방/자기진영 질량비 산출','로우');
INSERT INTO transfer_targets VALUES(137,'2026-summer','Karim Adeyemi','카림 아데예미',NULL,'Borussia Dortmund','LW,RW','RM','MEDIUM-HIGH',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'우측 윙어 브리프 후보 중 최저가(Tanswell: named 후보 중 가장 저렴, 선수가 도르트문트 이탈 희망). 서류상 브리프 정합 최상: PAC 96·#속도광·퀵스텝/래피드 PS + FC26 숙련 wm_winger·wm_insidefwd 보유(€43.5M 밸류, OVR82/POT86). 이전 세션 판정 재활용: "좌윙" 라벨과 달리 실측 움직임은 중앙-우측 — 빌라 좌측 슬롯 적합 0.25 vs RM 0.74 → 영입 시 우측 전용(툴 전술리포트 카드 기재). 단 당시 그리드가 저장되지 않아 커널 역할·침투 서명 재산출 필요.','Jacob Tanswell/The Athletic (via readastonvilla 2026-06-02); 이전 세션 실측 판정(좌 0.25 vs RM 0.74, fc26-heatmap.html 전술리포트)','PENDING MEASUREMENT — RM 0.74 판정만 승계, map25 미저장(2026-07-29 API 레이트리밋으로 재측정 실패). 다음 세션에서 그리드 재수집 후 fit_role/fit_sim 확정','아데예미');
